//! DI registration helpers for the durable payment webhook inbox.
//!
//! The application owns the database registration: call rust-ef's
//! `add_dbcontext` (or `add_dbcontext_keyed` + `use_default_entity_model`) for
//! the context the inbox should live in, then [`add_payment_inbox`]. Migrations
//! for the inbox table are generated by the official rust-ef tooling; this crate
//! neither creates schema at runtime nor declares extra routes.

use std::sync::Arc;

use rust_dix::{IServiceResolverExt, ScopeFactory, ServiceCollection};
use webx_core::route::ext::IServiceCollectionExt;
use webx_host::server::HostBuilder;

use crate::ef_inbox::EfPaymentInbox;
use crate::options::PaymentInboxOptions;
use crate::port::{IPaymentEventHandler, IPaymentInbox};
use crate::worker::PaymentInboxWorker;

/// Register the inbox port and its drain worker on a [`ServiceCollection`].
pub trait PaymentInboxServiceCollectionExt: Sized {
    /// Register `Arc<dyn IPaymentInbox>` and, when `options.enabled`, the
    /// [`PaymentInboxWorker`] background service.
    ///
    /// The application handler (`Arc<dyn IPaymentEventHandler>`) is resolved from
    /// DI on every tick, so register it yourself with `instance`/`scoped` (or
    /// use [`add_payment_inbox_with_handler`](Self::add_payment_inbox_with_handler)).
    ///
    /// Requires a scoped rust-ef `DbContext` registered with `add_dbcontext`;
    /// the inbox resolves an owned context from a fresh DI scope per operation.
    fn add_payment_inbox(self, options: PaymentInboxOptions) -> Self;

    /// Same as [`add_payment_inbox`](Self::add_payment_inbox), with an explicit
    /// handler registered as an instance (manual wiring, tests, and
    /// applications that prefer explicit composition).
    fn add_payment_inbox_with_handler(
        self,
        options: PaymentInboxOptions,
        handler: Arc<dyn IPaymentEventHandler>,
    ) -> Self;
}

impl PaymentInboxServiceCollectionExt for ServiceCollection {
    fn add_payment_inbox(self, options: PaymentInboxOptions) -> Self {
        add_payment_inbox(self, options, None)
    }

    fn add_payment_inbox_with_handler(
        self,
        options: PaymentInboxOptions,
        handler: Arc<dyn IPaymentEventHandler>,
    ) -> Self {
        add_payment_inbox(self, options, Some(handler))
    }
}

fn add_payment_inbox(
    services: ServiceCollection,
    options: PaymentInboxOptions,
    handler: Option<Arc<dyn IPaymentEventHandler>>,
) -> ServiceCollection {
    let max_attempts = options.max_attempts();
    let mut services = services.try_add_singleton::<dyn IPaymentInbox>(move |resolver| {
        let services = resolve_scope_factory(resolver);
        Arc::new(EfPaymentInbox::new(services, max_attempts)) as Arc<dyn IPaymentInbox>
    });

    if let Some(handler) = handler {
        services = services.instance::<dyn IPaymentEventHandler>(handler);
    }

    let worker_options = options.clone();
    services.add_background_service_with_if::<PaymentInboxWorker, _>(
        options.enabled,
        move |resolver| {
            let services = resolve_scope_factory(resolver);
            Arc::new(PaymentInboxWorker::new(services, worker_options.clone()))
        },
    )
}

/// Register the inbox on a [`HostBuilder`] (`add_payment_inbox(...)`).
pub trait PaymentInboxHostBuilderExt: Sized {
    /// Register the inbox port and (when enabled) the drain worker.
    fn add_payment_inbox(self, options: PaymentInboxOptions) -> Self;

    /// Register the inbox with an explicit application handler instance.
    fn add_payment_inbox_with_handler(
        self,
        options: PaymentInboxOptions,
        handler: Arc<dyn IPaymentEventHandler>,
    ) -> Self;
}

impl PaymentInboxHostBuilderExt for HostBuilder {
    fn add_payment_inbox(self, options: PaymentInboxOptions) -> Self {
        self.register(move |services| services.add_payment_inbox(options))
    }

    fn add_payment_inbox_with_handler(
        self,
        options: PaymentInboxOptions,
        handler: Arc<dyn IPaymentEventHandler>,
    ) -> Self {
        self.register(move |services| services.add_payment_inbox_with_handler(options, handler))
    }
}

/// The rust-dix built-in `ScopeFactory` is always resolvable from a built
/// provider; a failure here means the provider was built by hand without it.
fn resolve_scope_factory(resolver: &dyn rust_dix::IServiceResolver) -> Arc<dyn ScopeFactory> {
    resolver.resolve_arc::<dyn ScopeFactory>().expect(
        "rust-dix always provides the built-in Arc<dyn ScopeFactory>; \
         payment inbox registration requires a provider built by rust-dix",
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::port::IPaymentInbox;
    use crate::test_support::{event, registered_env, row_count, TestHandler};
    use webx_core::handler::IHostedService;

    #[tokio::test]
    async fn registers_inbox_port_handler_and_worker() {
        let handler = TestHandler::new();
        let provider = registered_env(
            PaymentInboxOptions::default(),
            Some(Arc::clone(&handler) as Arc<dyn IPaymentEventHandler>),
        )
        .await;

        let inbox = provider.get::<dyn IPaymentInbox>().expect("inbox port");
        inbox.record(event("evt_1")).await.expect("record");
        assert_eq!(row_count(&provider).await, 1);

        assert!(
            provider.get::<dyn IPaymentEventHandler>().is_ok(),
            "explicit handler is registered as an instance"
        );
        assert!(
            !provider.get_all::<dyn IHostedService>().is_empty(),
            "the drain worker is registered as a hosted service"
        );
    }

    #[tokio::test]
    async fn disabled_options_keep_the_port_but_skip_the_worker() {
        let provider = registered_env(PaymentInboxOptions::default().disabled(), None).await;
        assert!(provider.get::<dyn IPaymentInbox>().is_ok());
        assert!(provider.get_all::<dyn IHostedService>().is_empty());
    }

    #[test]
    fn host_builder_extension_is_implemented() {
        fn assert_ext<T: PaymentInboxHostBuilderExt>() {}
        assert_ext::<HostBuilder>();
    }
}
